3	import { useEffect } from "react";
4	import styles from "./QuoteShare.module.css";
5	
6	/**
7	 * Firefox / Safari polyfill for the Text Fragments URL standard
8	 * (`#:~:text=<head>,<tail>`). When a visitor arrives via a shared
9	 * "link to passage" URL, Chromium browsers scroll-and-highlight
10	 * natively via the `fragmentDirective` API. The other two engines
11	 * just leave the hash unparsed — this component covers them.
12	 *
13	 * Behavior:
14	 *   1. Detect a `:~:text=` directive in the current URL hash.
15	 *   2. Skip if the engine has native Text Fragments support
16	 *      (Chromium exposes `document.fragmentDirective`).
17	 *   3. Walk the article's text nodes, find the head (and optional
18	 *      tail) substring, scroll the surrounding block-level element
19	 *      into view, and apply a brief amber flash so the reader sees
20	 *      where the link landed.
21	 *
22	 * Failure modes are all silent: bad encoding, no match, no
23	 * `<article>` element — we just no-op. The user still has the page,
24	 * just without the auto-scroll.
25	 *
26	 * Mounted as a sibling of `<QuoteShare>` on chapter + story pages.
27	 */
28	export default function TextFragmentScroller() {
29	  useEffect(() => {
30	    if (typeof window === "undefined") return;
31	
32	    const hash = window.location.hash;
33	    if (!hash.includes(":~:text=")) return;
34	
35	    // Chromium handles this natively — bail out so we don't fight
36	    // the browser's own scroll/highlight pass.
37	    if (
38	      typeof document !== "undefined" &&
39	      "fragmentDirective" in document
40	    ) {
41	      return;
42	    }
43	
44	    const parsed = parseTextDirective(hash);
45	    if (!parsed) return;
46	
47	    // Defer the DOM walk until after the article has rendered. The
48	    // chapter page is a server component, so the article markup is
49	    // in the initial HTML — but RichText hydration can shift node
50	    // identity. requestAnimationFrame waits for the next paint;
51	    // double rAF gives hydration room on slow devices.
52	    let raf1 = 0;
53	    let raf2 = 0;
54	    let flashTimer: ReturnType<typeof setTimeout> | null = null;
55	
56	    raf1 = window.requestAnimationFrame(() => {
57	      raf2 = window.requestAnimationFrame(() => {
58	        const article = document.querySelector("article");
59	        if (!article) return;
60	
61	        const range = findTextRange(article, parsed.head, parsed.tail);
62	        if (!range) return;
63	
64	        const block = closestBlock(range.startContainer);
65	        const target = block ?? (range.startContainer.parentElement);
66	        if (!target) return;
67	
68	        target.scrollIntoView({ behavior: "smooth", block: "center" });
69	        target.classList.add(styles.fragmentFlash);
70	        flashTimer = setTimeout(() => {
71	          target.classList.remove(styles.fragmentFlash);
72	        }, 2400);
73	      });
74	    });
75	
76	    return () => {
77	      if (raf1) cancelAnimationFrame(raf1);
78	      if (raf2) cancelAnimationFrame(raf2);
79	      if (flashTimer) clearTimeout(flashTimer);
80	    };
81	  }, []);
82	
83	  return null;
84	}
85	
86	interface ParsedDirective {
87	  head: string;
88	  tail: string | null;
89	}
90	
91	/**
92	 * Parse `#:~:text=<head>` or `#:~:text=<head>,<tail>` out of a URL
93	 * hash. We only support the `start[,end]` form — share.ts always
94	 * emits that shape, so prefix/suffix variants from other sites
95	 * fall through to no-op (acceptable: we're not a general-purpose
96	 * implementation, just our own deep-link readback).
97	 */
98	function parseTextDirective(hash: string): ParsedDirective | null {
99	  // The directive can appear after a regular fragment + `:~:`. Strip
100	  // anything before the marker so URLs like `#section1:~:text=foo`
101	  // still parse.
102	  const markerIdx = hash.indexOf(":~:text=");
103	  if (markerIdx === -1) return null;
104	  const after = hash.slice(markerIdx + ":~:text=".length);
105	  // Stop at the first `&` — additional directives are out of scope.
106	  const directive = after.split("&")[0];
107	  if (!directive) return null;
108	
109	  // Single comma split is the start/end form. More commas would
110	  // imply prefix-,start,end,-suffix; we don't emit those and the
111	  // share UX never lands a reader on one, so we ignore them.
112	  const parts = directive.split(",");
113	  try {
114	    const head = decodeURIComponent(parts[0] ?? "");
115	    if (!head) return null;
116	    const tail = parts[1] ? decodeURIComponent(parts[1]) : null;
117	    return { head, tail };
118	  } catch {
119	    // Malformed percent-encoding — give up rather than throwing
120	    // during hydration.
121	    return null;
122	  }
123	}
124	
125	/**
126	 * Find a DOM Range inside `container` that spans from the first
127	 * occurrence of `head` to the end of the first occurrence of `tail`
128	 * (search resumes after `head`). When `tail` is null, the range is
129	 * just `head`. Returns null if either token is absent.
130	 *
131	 * Matching is case-insensitive and whitespace-collapsed — the
132	 * article HTML can contain newlines + indentation between tags that
133	 * shouldn't break the match against a single-line encoded fragment.
134	 */
135	function findTextRange(
136	  container: Element,
137	  head: string,
138	  tail: string | null,
139	): Range | null {
140	  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
141	  const nodes: Text[] = [];
142	  const nodeStarts: number[] = [];
143	  let combined = "";
144	  let cursor = walker.nextNode();
145	  while (cursor) {
146	    nodes.push(cursor as Text);
147	    nodeStarts.push(combined.length);
148	    combined += cursor.nodeValue ?? "";
149	    cursor = walker.nextNode();
150	  }
151	  if (combined.length === 0) return null;
152	
153	  // Normalize whitespace into single spaces while remembering, for
154	  // each normalized character, which absolute index in `combined`
155	  // it came from. The match runs against the normalized view; we
156	  // map back to the original for the Range construction.
157	  let normalized = "";
158	  const origIndex: number[] = [];
159	  let lastWasSpace = false;
160	  for (let i = 0; i < combined.length; i++) {
161	    const ch = combined[i];
162	    if (/\s/.test(ch)) {
163	      if (!lastWasSpace && normalized.length > 0) {
164	        normalized += " ";
165	        origIndex.push(i);
166	        lastWasSpace = true;
167	      }
168	    } else {
169	      normalized += ch;
170	      origIndex.push(i);
171	      lastWasSpace = false;
172	    }
173	  }
174	
175	  const normLower = normalized.toLowerCase();
176	  const headNorm = head.trim().replace(/\s+/g, " ").toLowerCase();
177	  if (!headNorm) return null;
178	  const headIdx = normLower.indexOf(headNorm);
179	  if (headIdx === -1) return null;
180	
181	  let endIdxNorm: number;
182	  if (tail) {
183	    const tailNorm = tail.trim().replace(/\s+/g, " ").toLowerCase();
184	    if (!tailNorm) return null;
185	    const tailStart = normLower.indexOf(tailNorm, headIdx + headNorm.length);
186	    if (tailStart === -1) return null;
187	    endIdxNorm = tailStart + tailNorm.length;
188	  } else {
189	    endIdxNorm = headIdx + headNorm.length;
190	  }
191	
192	  // Range bounds in `combined`.
193	  const startInCombined = origIndex[headIdx];
194	  const lastCharInCombined = origIndex[endIdxNorm - 1];
195	  const endInCombined = lastCharInCombined + 1;
196	
197	  const startLoc = locate(nodes, nodeStarts, startInCombined);
198	  const endLoc = locate(nodes, nodeStarts, lastCharInCombined);
199	  if (!startLoc || !endLoc) return null;
200	
201	  const range = document.createRange();
202	  try {
203	    range.setStart(startLoc.node, startLoc.offset);
204	    range.setEnd(endLoc.node, endLoc.offset + 1);
205	  } catch {
206	    return null;
207	  }
208	  // Sanity check — endInCombined unused after this; reference it
209	  // to keep the local readable + linter happy.
210	  void endInCombined;
211	  return range;
212	}
213	
214	interface NodeLocation {
215	  node: Text;
216	  offset: number;
217	}
218	
219	/** Binary-search the node containing `offset` in the combined text. */
220	function locate(
221	  nodes: Text[],
222	  starts: number[],
223	  offset: number,
224	): NodeLocation | null {
225	  if (nodes.length === 0) return null;
226	  let lo = 0;
227	  let hi = nodes.length - 1;
228	  while (lo < hi) {
229	    const mid = (lo + hi + 1) >>> 1;
230	    if (starts[mid] <= offset) lo = mid;
231	    else hi = mid - 1;
232	  }
233	  const node = nodes[lo];
234	  const offsetInNode = offset - starts[lo];
235	  // Guard against an offset past the node — shouldn't happen given
236	  // we built the offsets ourselves, but the DOM API throws on bad
237	  // ranges so we'd rather no-op than crash.
238	  if (offsetInNode < 0 || offsetInNode > (node.nodeValue?.length ?? 0)) {
239	    return null;
240	  }
241	  return { node, offset: offsetInNode };
242	}
243	
244	/**
245	 * Climb to the nearest block-level ancestor so the flash highlight
246	 * covers a sensible chunk (paragraph / blockquote / list item /
247	 * heading) rather than a single text node inside a `<strong>` or
248	 * `<em>`.
249	 */
250	function closestBlock(node: Node): HTMLElement | null {
251	  let el: Node | null = node;
252	  while (el && el.nodeType !== Node.ELEMENT_NODE) {
253	    el = el.parentNode;
254	  }
255	  if (!(el instanceof HTMLElement)) return null;
256	  return el.closest("p, blockquote, li, h1, h2, h3, h4, h5, h6");
257	}
