3	import { useEffect, useRef } from "react";
4	import type { ContentType } from "@/types";
5	import { getSessionToken } from "./session";
6	
7	const API_URL =
8	  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001/api";
9	
10	interface ReadTrackerOptions {
11	  contentType: ContentType;
12	  contentId: string;
13	}
14	
15	/**
16	 * Tracks how long the visitor spent on a reading page and fires a
17	 * `POST /read-sessions` beacon when they leave.
18	 *
19	 * The beacon API survives tab close where `fetch` would be killed,
20	 * so the recorded time is reliable even on bounce.
21	 *
22	 * Listens to `pagehide` and `visibilitychange` (catches tab switch,
23	 * minimize, navigation, app close). Also fires once on React unmount
24	 * — covers client-side route changes inside the SPA.
25	 *
26	 * Idempotent at the API layer: a duplicate beacon for the same
27	 * (contentType, contentId, sessionToken) is silently ignored, so
28	 * firing twice on a flaky exit is fine.
29	 */
30	export function useReadTracker({ contentType, contentId }: ReadTrackerOptions) {
31	  const enteredAtRef = useRef<number>(Date.now());
32	  const sentRef = useRef<boolean>(false);
33	
34	  useEffect(() => {
35	    enteredAtRef.current = Date.now();
36	    sentRef.current = false;
37	
38	    const sendSession = () => {
39	      if (sentRef.current) return;
40	      sentRef.current = true;
41	
42	      const sessionToken = getSessionToken();
43	      const timeSpentSeconds = Math.floor(
44	        (Date.now() - enteredAtRef.current) / 1000,
45	      );
46	
47	      const payload = JSON.stringify({
48	        contentType,
49	        contentId,
50	        sessionToken,
51	        timeSpentSeconds,
52	      });
53	
54	      // sendBeacon needs a Blob with the JSON content-type so NestJS's
55	      // ValidationPipe parses it as JSON, not form data.
56	      navigator.sendBeacon(
57	        `${API_URL}/read-sessions`,
58	        new Blob([payload], { type: "application/json" }),
59	      );
60	    };
61	
62	    const handleVisibilityChange = () => {
63	      if (document.visibilityState === "hidden") sendSession();
64	    };
65	
66	    window.addEventListener("pagehide", sendSession);
67	    document.addEventListener("visibilitychange", handleVisibilityChange);
68	
69	    return () => {
70	      window.removeEventListener("pagehide", sendSession);
71	      document.removeEventListener("visibilitychange", handleVisibilityChange);
72	      // Fire on React unmount as well — covers SPA route changes.
73	      sendSession();
74	    };
75	  }, [contentType, contentId]);
76	}
