14	/**
15	 * Honors the user's OS-level "reduce motion" preference. Components
16	 * that run reveal / stagger animations should bail out early when
17	 * this returns true. Always returns false on the server (no signal
18	 * available) so SSR markup matches the un-animated final state.
19	 */
20	export function prefersReducedMotion(): boolean {
21	  if (typeof window === 'undefined') return false;
22	  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
23	}
